CREATE TABLE knowledge_base(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(128),description VARCHAR(1000),status VARCHAR(16),create_by BIGINT,update_by BIGINT,create_time TIMESTAMP,update_time TIMESTAMP,deleted TINYINT DEFAULT 0);
CREATE TABLE knowledge_document(id BIGINT AUTO_INCREMENT PRIMARY KEY,knowledge_base_id BIGINT,file_name VARCHAR(255),original_name VARCHAR(255),file_type VARCHAR(16),file_size BIGINT,storage_path VARCHAR(512),status VARCHAR(32),content_hash VARCHAR(64),version INT,visibility VARCHAR(16) DEFAULT 'PUBLIC',parse_error VARCHAR(1000),create_by BIGINT,create_time TIMESTAMP,update_time TIMESTAMP,deleted TINYINT DEFAULT 0);
CREATE TABLE knowledge_chunk(id BIGINT AUTO_INCREMENT PRIMARY KEY,document_id BIGINT,chunk_index INT,content CLOB,token_count INT,embedding_status VARCHAR(32),embedding_model VARCHAR(128),indexed_at TIMESTAMP,page_number INT,metadata_json CLOB,create_time TIMESTAMP);
